def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    if row < 0 or row >= 64 or col < 0 or col >= 64:
        return board

    old_char = board[row][col]
    if old_char == 'g':
        new_char = 'N'
    elif old_char == 'N':
        new_char = 'g'
    else:
        return board

    board[row][col] = new_char

    if new_char == 'N':
        for i in range(max(0, row-1), min(64, row+2)):
            for j in range(max(0, col-1), min(64, col+2)):
                if board[i][j] == 'g':
                    board[i][j] = 'N'
    else:
        for i in range(max(0, row-1), min(64, row+2)):
            for j in range(max(0, col-1), min(64, col+2)):
                if board[i][j] == 'N':
                    board[i][j] = 'g'

    if row == 0:
        board[row][col] = 'G'

    return ["".join(row) for row in board]
